import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"একচেটিয়া বিরোধী আইন","description":"","frontmatter":{},"headers":[],"relativePath":"bn/47-反垄断法.md","filePath":"bn/47-反垄断法.md","lastUpdated":null}'),d={name:"bn/47-反垄断法.md"};function e(o,t,h,n,s,b){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="একচেটিয়া-বিরোধী-আইন" tabindex="-1">একচেটিয়া বিরোধী আইন <a class="header-anchor" href="#একচেটিয়া-বিরোধী-আইন" aria-label="Permalink to &quot;একচেটিয়া বিরোধী আইন&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>47</td></tr><tr><td>মডিউল</td><td>আইনি ব্যবস্থা এবং প্রশাসনিক কাঠামো</td></tr><tr><td>মূল কীওয়ার্ড</td><td>একচেটিয়া বিরোধী, লুঠেরা বিরোধী, বাজার প্রতিযোগিতা, সম্পদ একচেটিয়া, সাধনা একচেটিয়া</td></tr></tbody></table><h2 id="_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-মূল-নীতি" tabindex="-1">1. আইন প্রণয়নের উদ্দেশ্য এবং মূল নীতি <a class="header-anchor" href="#_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-মূল-নীতি" aria-label="Permalink to &quot;1. আইন প্রণয়নের উদ্দেশ্য এবং মূল নীতি&quot;">​</a></h2><p>《একচেটিয়া বিরোধী আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার পাঁচটি সহায়ক আইনের একটি, এবং এর উদ্দেশ্য হল একচেটিয়া আচরণ প্রতিরোধ এবং বন্ধ করা, বাজারের ন্যায়বিচারপূর্ণ প্রতিযোগিতা রক্ষা করা, অর্থনৈতিক কার্যকারিতা বৃদ্ধি করা, ভোক্তার স্বার্থ এবং সামাজিক জনকল্যাণের স্বার্থ রক্ষা করা, এবং সিম্বায়োসিস অর্থনীতির সুস্থ উন্নয়নকে প্রচার করা। অ্যাঙ্কার সিম্বায়োসিস সভ্যতায়, একচেটিয়া বিরোধী শুধুমাত্র ঐতিহ্যবাহী অর্থনৈতিক ক্ষেত্রের একচেটিয়ার বিরুদ্ধে নয়, বরং সাধনা সম্পদ একচেটিয়া, জ্ঞান একচেটিয়া এবং位面 একচেটিয়া ইত্যাদি বিশেষ রূপগুলোর বিরুদ্ধেও কাজ করে।</p><p>এই আইন নিম্নলিখিত মূল নীতি স্থাপন করে:</p><table tabindex="0"><thead><tr><th>নীতি</th><th>অন্তর্নিহিত অর্থ</th></tr></thead><tbody><tr><td>ন্যায়বিচারপূর্ণ প্রতিযোগিতা নীতি</td><td>ন্যায়বিচারপূর্ণ প্রতিযোগিতার বাজার ব্যবস্থা রক্ষা করা, প্রতিযোগিতা বাদ দেওয়া বা সীমিত করা একচেটিয়া আচরণ নিষিদ্ধ</td></tr><tr><td>লুঠেরা বিরোধী নীতি</td><td>একচেটিয়া বিরোধীর মূল হল লুঠেরা বিরোধী, এবং একচেটিয়া শক্তিকে তার একচেটিয়া অবস্থানের মাধ্যমে সকল জীবের স্বার্থ লুঠ করতে বাধা দেওয়া</td></tr><tr><td>সম্পদ উন্মুক্ত নীতি</td><td>পাবলিক সাধনা সম্পদ এবং মৌলিক জ্ঞান অবশ্যই সমগ্র সমাজের জন্য উন্মুক্ত হতে হবে, এবং ব্যক্তিগত একচেটিয়া নিষিদ্ধ</td></tr><tr><td>কার্যকারিতা এবং ন্যায়বিচারের ভারসাম্য নীতি</td><td>একচেটিয়া বিরোধীকে অবশ্যই প্রতিযোগিতার কার্যকারিতা রক্ষা করতে হবে, সেইসাথে অতিরিক্ত বিক্ষিপ্ততার কারণে সম্পদের অপচয় প্রতিরোধ করতে হবে</td></tr><tr><td>আন্তঃ位面 প্রযোজ্য নীতি</td><td>একচেটিয়া বিরোধী আইন হেঙ্গুয়ানঝৌর ভেতরের সমস্ত位面 এবং বাজারে প্রযোজ্য, এবং আন্তঃ位面 একচেটিয়াও নিয়ন্ত্রণের অধীন</td></tr></tbody></table><h2 id="_2-একচেটিয়া-আচরণের-ধরন" tabindex="-1">2. একচেটিয়া আচরণের ধরন <a class="header-anchor" href="#_2-একচেটিয়া-আচরণের-ধরন" aria-label="Permalink to &quot;2. একচেটিয়া আচরণের ধরন&quot;">​</a></h2><p>এই আইন দ্বারা নিয়ন্ত্রিত একচেটিয়া আচরণে নিম্নলিখিত চারটি ধরন অন্তর্ভুক্ত:</p><h3 id="ক-একচেটিয়া-চুক্তি" tabindex="-1">(ক) একচেটিয়া চুক্তি <a class="header-anchor" href="#ক-একচেটিয়া-চুক্তি" aria-label="Permalink to &quot;(ক) একচেটিয়া চুক্তি&quot;">​</a></h3><p>একচেটিয়া চুক্তি বলতে বোঝায় প্রতিযোগিতা বাদ দেওয়া, সীমিত করা চুক্তি, সিদ্ধান্ত বা অন্যান্য সহযোগী আচরণ, এবং এর মধ্যে অন্তর্ভুক্ত:</p><ol><li><strong>অনুভূমিক একচেটিয়া চুক্তি</strong>: প্রতিযোগিতার সম্পর্কযুক্ত ব্যবসায়ীদের মধ্যে স্থির মূল্য, উৎপাদন সীমিত, বাজার বিভাজন, যৌথ বিরোধিতা লেনদেন ইত্যাদি চুক্তি।</li><li><strong>অনুভূমিক একচেটিয়া চুক্তি</strong>: ব্যবসায়ী এবং লেনদেনের সম্পর্কযুক্ত ব্যক্তির মধ্যে স্থির পুনর্বিক্রয় মূল্য, সর্বনিম্ন পুনর্বিক্রয় মূল্য সীমিত ইত্যাদি চুক্তি।</li><li><strong>সাধনা সম্পদ একচেটিয়া চুক্তি</strong>: সাধনা ধর্মীয় সংস্থাগুলোর মধ্যে সাধনা সম্পদ অঞ্চল বিভাজন, সম্পদের মূল্য একীভূত, সম্পদের সরবরাহ সীমিত ইত্যাদি চুক্তি।</li><li><strong>জ্ঞান একচেটিয়া চুক্তি</strong>: শিক্ষা প্রতিষ্ঠান এবং সাধনা ধর্মীয় সংস্থাগুলোর মধ্যে সাধনা পদ্ধতি বন্ধ, জ্ঞান প্রচার সীমিত, টিউশন ফি মানদণ্ড একীভূত ইত্যাদি চুক্তি।</li></ol><h3 id="খ-বাজারের-আধিপত্যের-অপব্যবহার" tabindex="-1">(খ) বাজারের আধিপত্যের অপব্যবহার <a class="header-anchor" href="#খ-বাজারের-আধিপত্যের-অপব্যবহার" aria-label="Permalink to &quot;(খ) বাজারের আধিপত্যের অপব্যবহার&quot;">​</a></h3><p>বাজারের আধিপত্য বলতে বোঝায় ব্যবসায়ী সম্পর্কিত বাজারে পণ্যের মূল্য, পরিমাণ বা অন্যান্য লেনদেনের শর্ত নিয়ন্ত্রণ করতে সক্ষম, অথবা অন্য ব্যবসায়ীদের সম্পর্কিত বাজারে প্রবেশে বাধা দেওয়া বা প্রভাব ফেলতে সক্ষম বাজারের অবস্থান। বাজারের আধিপত্যের অপব্যবহারের আচরণে অন্তর্ভুক্ত:</p><table tabindex="0"><thead><tr><th>আচরণের ধরন</th><th>নির্দিষ্ট প্রকাশ</th></tr></thead><tbody><tr><td>অন্যায্য মূল্য নির্ধারণ</td><td>অন্যায্য উচ্চ মূল্যে পণ্য বিক্রি করা বা অন্যায্য কম মূল্যে পণ্য কেনা</td></tr><tr><td>লুঠেরা মূল্য নির্ধারণ</td><td>বৈধ কারণ ছাড়া, খরচের নিচে মূল্যে পণ্য বিক্রি করা, প্রতিযোগীদের বাদ দেওয়া</td></tr><tr><td>লেনদেন প্রত্যাখ্যান</td><td>বৈধ কারণ ছাড়া, লেনদেনের সম্পর্কযুক্ত ব্যক্তির সাথে লেনদেন করতে অস্বীকার করা</td></tr><tr><td>লেনদেন সীমিত</td><td>বৈধ কারণ ছাড়া, লেনদেনের সম্পর্কযুক্ত ব্যক্তিকে শুধুমাত্র তার সাথে লেনদেন করতে সীমিত করা</td></tr><tr><td>জোড়া বিক্রি</td><td>বৈধ কারণ ছাড়া পণ্য জোড়া বিক্রি করা, বা লেনদেনের সময় অন্যান্য অন্যায্য শর্ত যোগ করা</td></tr><tr><td>পার্থক্যপূর্ণ ব্যবহার</td><td>বৈধ কারণ ছাড়া, একই শর্তের লেনদেনের সম্পর্কযুক্ত ব্যক্তিদের সাথে লেনদেনের মূল্য ইত্যাদি শর্তে পার্থক্যপূর্ণ ব্যবহার করা</td></tr><tr><td>সাধনা সম্পদ বন্ধ</td><td>সাধনা সম্পদ একচেটিয়া অবস্থান ব্যবহার করে, প্রতিযোগী বা ভোক্তাকে প্রয়োজনীয় সম্পদ প্রদান করতে অস্বীকার করা</td></tr><tr><td>জ্ঞান বন্ধ</td><td>জ্ঞান একচেটিয়া অবস্থান ব্যবহার করে, মৌলিক সাধনা পদ্ধতি বন্ধ করা, শিক্ষার্থীদের বাধ্য করে উচ্চ ফি প্রদান করতে</td></tr></tbody></table><h3 id="গ-ব্যবসায়ীদের-কেন্দ্রীভূতকরণ" tabindex="-1">(গ) ব্যবসায়ীদের কেন্দ্রীভূতকরণ <a class="header-anchor" href="#গ-ব্যবসায়ীদের-কেন্দ্রীভূতকরণ" aria-label="Permalink to &quot;(গ) ব্যবসায়ীদের কেন্দ্রীভূতকরণ&quot;">​</a></h3><p>ব্যবসায়ীদের কেন্দ্রীভূতকরণ বলতে বোঝায় নিম্নলিখিত পরিস্থিতি: ব্যবসায়ীদের একীভূতকরণ; ব্যবসায়ী শেয়ার বা সম্পদ অর্জনের মাধ্যমে অন্য ব্যবসায়ীদের উপর নিয়ন্ত্রণ ক্ষমতা অর্জন; ব্যবসায়ী চুক্তি ইত্যাদি মাধ্যমে অন্য ব্যবসায়ীদের উপর নিয়ন্ত্রণ ক্ষমতা অর্জন বা অন্য ব্যবসায়ীদের উপর সিদ্ধান্তমূলক প্রভাব ফেলতে সক্ষম।</p><p>ঘোষণার মানদণ্ডে পৌঁছানো ব্যবসায়ীদের কেন্দ্রীভূতকরণ, আগে একচেটিয়া বিরোধী কার্যকরী সংস্থাকে ঘোষণা করতে হবে, এবং ঘোষণা না করা কেন্দ্রীভূতকরণ বাস্তবায়ন করতে পারবে না। একচেটিয়া বিরোধী কার্যকরী সংস্থা ব্যবসায়ীদের কেন্দ্রীভূতকরণ পরীক্ষা করার সময়, নিম্নলিখিত বিষয়গুলো বিবেচনা করতে হবে:</p><ol><li>কেন্দ্রীভূতকরণে অংশগ্রহণকারী ব্যবসায়ীদের সম্পর্কিত বাজারে বাজারের অংশ এবং বাজারের উপর তাদের নিয়ন্ত্রণ ক্ষমতা।</li><li>সম্পর্কিত বাজারের বাজারের কেন্দ্রীভূতকরণ।</li><li>ব্যবসায়ীদের কেন্দ্রীভূতকরণের বাজারে প্রবেশ, প্রযুক্তিগত অগ্রগতির উপর প্রভাব।</li><li>ব্যবসায়ীদের কেন্দ্রীভূতকরণের ভোক্তা এবং অন্যান্য সম্পর্কিত ব্যবসায়ীদের উপর প্রভাব।</li><li>ব্যবসায়ীদের কেন্দ্রীভূতকরণের সাধনা সম্পদ উন্মুক্ত এবং জ্ঞান প্রচারের উপর প্রভাব।</li><li>ব্যবসায়ীদের কেন্দ্রীভূতকরণের জাতীয় অর্থনৈতিক উন্নয়ন এবং সকল প্রজাতির সহযোগিতামূলক অগ্রগতির উপর প্রভাব।</li></ol><h3 id="ঘ-প্রশাসনিক-ক্ষমতার-অপব্যবহার-করে-প্রতিযোগিতা-বাদ-দেওয়া-সীমিত-করা" tabindex="-1">(ঘ) প্রশাসনিক ক্ষমতার অপব্যবহার করে প্রতিযোগিতা বাদ দেওয়া, সীমিত করা <a class="header-anchor" href="#ঘ-প্রশাসনিক-ক্ষমতার-অপব্যবহার-করে-প্রতিযোগিতা-বাদ-দেওয়া-সীমিত-করা" aria-label="Permalink to &quot;(ঘ) প্রশাসনিক ক্ষমতার অপব্যবহার করে প্রতিযোগিতা বাদ দেওয়া, সীমিত করা&quot;">​</a></h3><p>প্রশাসনিক সংস্থা এবং আইন, বিধি দ্বারা অনুমোদিত জনকল্যাণের কাজ পরিচালনার ক্ষমতাসম্পন্ন সংস্থা প্রশাসনিক ক্ষমতার অপব্যবহার করতে পারবে না, এবং নিম্নলিখিত আচরণ বাস্তবায়ন করতে পারবে না:</p><ol><li>ইউনিট বা ব্যক্তিকে তার নির্দিষ্ট ব্যবসায়ী দ্বারা প্রদত্ত পণ্য পরিচালনা, কেনা, ব্যবহার করতে সীমিত বা পরোক্ষভাবে সীমিত করা।</li><li>অঞ্চলের মধ্যে,位面ের মধ্যে পণ্যের স্বাধীন প্রবাহে বাধা দেওয়া।</li><li>বাইরের অঞ্চলের ব্যবসায়ী, বাইরের位面ের ব্যবসায়ীদের স্থানীয় টেন্ডার এবং বিডিং কার্যক্রমে অংশ নেওয়া থেকে বাদ দেওয়া বা সীমিত করা।</li><li>বাইরের অঞ্চলের ব্যবসায়ী, বাইরের位面ের ব্যবসায়ীদের স্থানীয় বিনিয়োগ বা শাখা প্রতিষ্ঠা থেকে বাদ দেওয়া বা সীমিত করা।</li><li>ব্যবসায়ীদের এই আইনে নির্ধারিত একচেটিয়া আচরণে জড়িত হতে বাধ্য করা।</li><li>প্রতিযোগিতা বাদ দেওয়া, সীমিত করা বিষয়বস্তু সহ বিধি প্রণয়ন করা।</li></ol><h2 id="_3-সাধনা-ক্ষেত্রের-বিশেষ-একচেটিয়া-বিরোধী-নিয়ম" tabindex="-1">3. সাধনা ক্ষেত্রের বিশেষ একচেটিয়া বিরোধী নিয়ম <a class="header-anchor" href="#_3-সাধনা-ক্ষেত্রের-বিশেষ-একচেটিয়া-বিরোধী-নিয়ম" aria-label="Permalink to &quot;3. সাধনা ক্ষেত্রের বিশেষ একচেটিয়া বিরোধী নিয়ম&quot;">​</a></h2><p>সাধনা ক্ষেত্র হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার একচেটিয়া বিরোধীর গুরুত্বপূর্ণ ক্ষেত্র, এবং এই আইন বিশেষ নিয়ম স্থাপন করে:</p><ol><li><strong>মৌলিক পদ্ধতি উন্মুক্ত করার বাধ্যতা</strong>: তিনশত সেট মূল সাধনা ব্যবস্থার মৌলিক পদ্ধতি জনকল্যাণ জ্ঞানের অন্তর্গত, এবং কোনো সংস্থা বা ব্যক্তি একচেটিয়া, বন্ধ বা ফি নিয়ে শেখাতে পারবে না।</li><li><strong>সাধনা সম্পদ ন্যায়বিচারপূর্ণ বণ্টন</strong>: পাবলিক সাধনা সম্পদ যৌথ উৎপাদন চুক্তি ব্যবস্থার মাধ্যমে ন্যায়বিচারপূর্ণভাবে বণ্টিত হয়, এবং ধর্মীয় সংস্থা বা ব্যক্তি উচ্চমানের সাধনা সম্পদ একচেটিয়া করতে পারবে না।</li><li><strong>সাধনা বৈষম্য নিষিদ্ধ</strong>: সাধনা ধর্মীয় সংস্থা ভর্তি এবং শিক্ষাদানে প্রজাতি, উত্স, সাধনার স্তর ইত্যাদি ভিত্তিতে বৈষম্যমূলক শর্ত স্থাপন করতে পারবে না।</li><li><strong>উচ্চস্তরের জ্ঞান শেয়ার করার বাধ্যতা</strong>:位面 সর্বোচ্চ শক্তিশালী ব্যক্তির মানদণ্ডে পৌঁছানো সাধক, যুক্তিসঙ্গত বৌদ্ধিক সম্পত্তি সুরক্ষার শর্তে, সমাজের সাথে তার সাধনার অভিজ্ঞতা এবং গবেষণার ফলাফল শেয়ার করার বাধ্যতা রাখে।</li><li><strong>位面 উন্নয়ন একচেটিয়া বিরোধী</strong>: নতুন位面ের উন্নয়নের অধিকার খোলা প্রতিযোগিতার মাধ্যমে বণ্টিত হয়, এবং কয়েকটি শক্তি位面 উন্নয়নের অধিকার একচেটিয়া করতে পারবে না।</li></ol><h2 id="_4-একচেটিয়া-বিরোধী-কার্যকরী-সংস্থা" tabindex="-1">4. একচেটিয়া বিরোধী কার্যকরী সংস্থা <a class="header-anchor" href="#_4-একচেটিয়া-বিরোধী-কার্যকরী-সংস্থা" aria-label="Permalink to &quot;4. একচেটিয়া বিরোধী কার্যকরী সংস্থা&quot;">​</a></h2><p>রাষ্ট্র একচেটিয়া বিরোধী কার্যকরী সংস্থা স্থাপন করে, এবং একচেটিয়া বিরোধী কার্যকরী কাজের জন্য দায়বদ্ধ, এবং নিম্নলিখিত কর্তব্য পালন করে:</p><ol><li>প্রতিযোগিতা নীতি সম্পর্কিত গবেষণা এবং খসড়া প্রণয়ন।</li><li>বাজারের সামগ্রিক প্রতিযোগিতার পরিস্থিতি তদন্ত, মূল্যায়ন, এবং মূল্যায়ন রিপোর্ট প্রকাশ।</li><li>একচেটিয়া বিরোধী নির্দেশিকা প্রণয়ন এবং প্রকাশ।</li><li>একচেটিয়া বিরোধী প্রশাসনিক কার্যকরী কাজ সমন্বয়।</li><li>একচেটিয়া চুক্তি, বাজারের আধিপত্যের অপব্যবহার, অবৈধভাবে ব্যবসায়ীদের কেন্দ্রীভূতকরণ বাস্তবায়ন ইত্যাদি মামলা তদন্ত এবং শাস্তি।</li><li>প্রশাসনিক ক্ষমতার অপব্যবহার করে প্রতিযোগিতা বাদ দেওয়া, সীমিত করা আচরণ তদন্ত এবং শাস্তি।</li></ol><p>একচেটিয়া বিরোধী কার্যকরী সংস্থা আইন অনুযায়ী স্বাধীনভাবে কর্তব্য পালন করে, এবং প্রশাসনিক সংস্থা, সামাজিক সংস্থা এবং ব্যক্তির হস্তক্ষেপ থেকে মুক্ত।</p><h2 id="_5-আইনি-দায়বদ্ধতা" tabindex="-1">5. আইনি দায়বদ্ধতা <a class="header-anchor" href="#_5-আইনি-দায়বদ্ধতা" aria-label="Permalink to &quot;5. আইনি দায়বদ্ধতা&quot;">​</a></h2><p>এই আইনের বিধান লঙ্ঘন করা কার্যক্রম, অপরাধের গুরুত্ব অনুযায়ী নিম্নলিখিত দায়বদ্ধতা গ্রহণ করবে:</p><ul><li>একচেটিয়া চুক্তি প্রণয়ন এবং বাস্তবায়ন করলে, অবৈধ আচরণ বন্ধ করার নির্দেশ, অবৈধ আয় জব্দ, এবং আগের বছরের বিক্রয় আয়ের এক শতাংশ থেকে দশ শতাংশ পর্যন্ত জরিমানা।</li><li>বাজারের আধিপত্যের অপব্যবহার করলে, অবৈধ আচরণ বন্ধ করার নির্দেশ, অবৈধ আয় জব্দ, এবং আগের বছরের বিক্রয় আয়ের এক শতাংশ থেকে দশ শতাংশ পর্যন্ত জরিমানা।</li><li>অবৈধভাবে ব্যবসায়ীদের কেন্দ্রীভূতকরণ বাস্তবায়ন করলে, কেন্দ্রীভূতকরণ বাস্তবায়ন বন্ধ করার নির্দেশ, নির্ধারিত সময়ের মধ্যে শেয়ার বা সম্পদ বিক্রয়, নির্ধারিত সময়ের মধ্যে ব্যবসা হস্তান্তর, এবং পঞ্চাশ হাজার ইউয়ানের নিচে জরিমানা।</li><li>প্রশাসনিক ক্ষমতার অপব্যবহার করে প্রতিযোগিতা বাদ দেওয়া, সীমিত করলে, উচ্চতর সংস্থা দ্বারা সংশোধন করার নির্দেশ, এবং সরাসরি দায়ী প্রশাসক এবং অন্যান্য সরাসরি দায়ী ব্যক্তিকে আইন অনুযায়ী শাস্তি দেওয়া হবে।</li><li>একচেটিয়া আচরণ অন্যের ক্ষতি সাধন করলে, আইন অনুযায়ী দেওয়ানি ক্ষতিপূরণের দায়বদ্ধতা গ্রহণ করবে।</li><li>গুরুতর অপরাধ যা অপরাধ গঠন করে, আইন অনুযায়ী ফৌজদারি দায়বদ্ধতা আরোপ করা হবে।</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>《একচেটিয়া বিরোধী আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার লুঠেরা বিরোধী তত্ত্বের অর্থনৈতিক এবং সাধনা ক্ষেত্রের আইনি অস্ত্র। এটি একচেটিয়া চুক্তি, বাজারের আধিপত্যের অপব্যবহার, ব্যবসায়ীদের কেন্দ্রীভূতকরণ এবং প্রশাসনিক একচেটিয়া নিয়ন্ত্রণ করার মাধ্যমে, বিশেষ করে সাধনা সম্পদ একচেটিয়া এবং জ্ঞান একচেটিয়ার বিরুদ্ধে বিশেষ নিয়ম স্থাপন করার মাধ্যমে, বাজার প্রতিযোগিতা এবং সাধনা সম্পদের ন্যায়বিচারপূর্ণ উন্মুক্ততা নিশ্চিত করে, এবং একচেটিয়াকে সকল জীব লুঠ করার নতুন রূপ হওয়া থেকে বাধা দেয়, এবং সকল প্রজাতির সহযোগিতামূলক অগ্রগতির জন্য ন্যায়বিচারপূর্ণ প্রতিযোগিতার প্রশাসনিক পরিবেশ রক্ষা করে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>40-共生宪法总纲 (সিম্বায়োসিস সংবিধানের মূল নীতি)</li><li>42-消费者保护法 (ভোক্তা সংরক্ষণ আইন)</li><li>18-修炼资源开放机制 (সাধনা সম্পদ উন্মুক্ত করার প্রক্রিয়া)</li><li>04-反掠夺主义核心论纲 (লুঠেরা বিরোধী তত্ত্বের মূল নীতি)</li></ul>',35)])])}const _=a(d,[["render",e]]);export{c as __pageData,_ as default};
